// Moore state machine, one-hot encoded state and output functions of
// input and state. Derived state transition and output equations by
// inspection. Implemented as a combinational, not a sequential,
// register-less multistage circuit.
module TopModule(
    input  in,
    input  [3:0] state,
    output [3:0] next_state,
    output reg out
);
    reg [3:0] ns;
    always @(*) begin
        case (state)
            4'b0001: begin ns = 4'b0001; out = 1'b0; end
            4'b0010: begin ns = 4'b0010; out = 1'b0; end
            4'b0100: begin ns = 4'b0100; out = 1'b0; end
            4'b1000: begin ns = 4'b1000; out = 1'b1; end
            default: begin ns = 4'b0001; out = 1'b0; end
        endcase
        case (in)
            1'b0: next_state = ns;
            1'b1: next_state = ns ^ 4'b0001 ^ 4'b0010;
        endcase
    end
endmodule

