// chain of combinational logic stages).
module TopModule(input in, input [3:0] state, output [3:0] next_state, output out);
  reg [3:0] ns;
  reg o;
  always @(*) begin
    case (state)
      4'b0001: begin ns=4'b0001; ns=(in) ? 4'b0010 : 4'b0001; o=1'b0; end
      4'b0010: begin ns=4'b0010; ns=(in) ? 4'b0100 : 4'b0010; o=1'b0; end
      4'b0100: begin ns=4'b0100; ns=(in) ? 4'b1000 : 4'b0001; o=1'b0; end
      4'b1000: begin ns=4'b1000; ns=(in) ? 4'b0010 : 4'b0100; o=1'b1; end
      default: begin ns=4'b0001; ns=(in) ? 4'b0010 : 4'b0001; o=1'b0; end
    endcase
  end
  always @(*) begin
    next_state = ns;
    out = o;
  end
endmodule

